function validate([points]) {
  if (!Array.isArray(points) || points.length < 2 || points.length > 1000) return 'points needs 2 to 1000 points.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each coordinate is an integer between -10^9 and 10^9.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'The points must be distinct.';
    seen.add(key);
  }
  return null;
}

