function numberOfPairs(points) {
  points.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const n = points.length;
  let count = 0;

  for (let i = 0; i < n; i++) {
    const top = points[i][1];
    let highest = -Infinity;
    for (let j = i + 1; j < n; j++) {
      const y = points[j][1];
      if (y > top) {
        continue;
      }
      if (y > highest) {
        count++;
        highest = y;
      }
    }
  }
  return count;
}

