function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const build = (n, lo, hi) => {
    const seen = new Set();
    const points = [];
    while (points.length < n) {
      const x = int(lo, hi);
      const y = int(lo, hi);
      const key = x + ',' + y;
      if (seen.has(key)) continue;
      seen.add(key);
      points.push([x, y]);
    }
    return points;
  };
  if (size === 'small') {
    const shape = int(0, 3);
    const n = int(2, 9);
    // Tiny grids create many shared x and y values, so segment fences and border hits are common.
    if (shape === 0) return [build(Math.min(n, 4), 0, 1)];
    if (shape === 1) return [build(n, 0, 3)];
    if (shape === 2) return [build(n, -6, 6)];
    return [build(n, -1000000000, 1000000000)];
  }
  const shape = int(0, 2);
  if (shape === 0) return [build(1000, -1000000000, 1000000000)];
  if (shape === 1) return [build(1000, -20, 20)];
  // A descending staircase with noise: many pairs are good.
  const seen = new Set();
  const points = [];
  while (points.length < 1000) {
    const x = int(0, 1500);
    const y = 1500 - x + int(-30, 30);
    const key = x + ',' + y;
    if (seen.has(key)) continue;
    seen.add(key);
    points.push([x, y]);
  }
  return [points];
}
